-- TASK-281: review-only revisions of 19 M03 candidate questions.
-- Idempotent; refuses all published content. Full before/after snapshots in QA JSON.
BEGIN;
DO $task281$
DECLARE
  p jsonb; v_id uuid; v_stem text; v_status text; v_code text;
  i integer; idx integer; v_ord jsonb; v_opt uuid;
BEGIN
  FOR p IN SELECT value FROM jsonb_array_elements('[{"code": "M03-S26-E02-07", "prev_stem": "E4 katakdagi formulani G6 ga ko‘chirishda havolalarni hisoblash jarayoni bosqichlarini mantiqiy tartibga keltiring.", "stem_md": "E4 katakka hali formula yozilmagan, G6 katak ham bo‘sh. Quyidagi topshiriqda formulani ko‘chirib, natijasini tekshirish uchun bajariladigan bog‘liq amallarni tartiblang.", "explanation_md": "Avval E4 da formula bo‘lishi kerak; keyin u G6 ga nusxalanadi. E4→G6 siljish (+2 ustun, +2 satr): `=$B$2+C5*E$1`. Shundan keyin qiymat manba kataklardagi sonlar asosida tekshiriladi. Havolalarni tekshirish hisoblangan natijaga ishonishdan oldingi nazorat bosqichidir.", "difficulty": 5, "format": "Y3", "options": null, "steps": ["1) G6 katakdagi hosil bo‘lgan havolalarni ko‘chirish qoidalariga ko‘ra tekshirish", "2) E4 katakka `=$B$2+A3*C$1` formulasini kiritish", "3) E4 dagi formulani G6 katakka nusxalash", "4) Tekshirilgan G6 formulasining qiymatini manba kataklar bilan solishtirish"], "order": [2, 3, 1, 4]}, {"code": "M03-S26-E03-07", "prev_stem": "Tekshirilgan (aniq moslikli) VLOOKUP qidiruv formulasini tuzish ish tartibini berilgan bosqichlardan yig‘ing.", "stem_md": "A2:B4 jadvalining birinchi ustunida 60, 70, 80 sonlari bor. D2 katakda esa `\"60a\"` matni yozilgan. E2 katak bo‘sh. Exact-match VLOOKUP bilan qidirishdagi xatoni aniqlash va tuzatish ketma-ketligini joylang.", "explanation_md": "E2 ga aniq qidiruv formulasi kiritiladi; `\"60a\"` A ustunidagi `60` ga mos kelmagani uchun `#N/A` kuzatiladi. Xatoga sabab bo‘lgan qidiruv kaliti tekshiriladi va D2 raqamli 60 ga tuzatiladi. `FALSE` exact match talab qiladi.", "difficulty": 4, "format": "Y3", "options": null, "steps": ["1) E2 katakda `#N/A` xatosi chiqqanini kuzatish", "2) D2 dagi `\"60a\"` matni jadvaldagi `60` soniga teng emasligini aniqlash", "3) D2 ni `60` soniga tuzatib, E2 formulasini qayta hisoblatish", "4) E2 ga `=VLOOKUP(D2,A2:B4,2,FALSE)` formulasini kiritish"], "order": [4, 1, 2, 3]}, {"code": "M03-S26-P01-03", "prev_stem": "Tayyor shablon asosida maktab konferensiyasi uchun bir xil ko‘rinishli 12 ta slayd yaratish ish tartibini bog‘liq bosqichlarda joylashtiring.", "stem_md": "Yangi PowerPoint taqdimoti yaratilyapti. Talab: umumiy sarlavha formati **slaydlar yaratilishidan oldin** Slide Master’da sozlansin, so‘ng 12 slayd qo‘shilib yakuniy namoyish tekshirilsin. Amallarni tartiblang.", "explanation_md": "Bo‘sh taqdimot ochiladi → barcha yangi slaydlar uchun Slide Master maketi avval sozlanadi → 12 slayd shu maketlardan yaratiladi → yakunda Slide Show’da ko‘rinish tekshiriladi. Savolning maxsus sharti maketni slaydlar yaratilishidan oldin sozlashni talab qiladi.", "difficulty": 4, "format": "Y3", "options": null, "steps": ["1) Kerakli maketlar asosida 12 ta slayd yaratib mazmunni joylash", "2) Yangi bo‘sh taqdimot ochish", "3) Hali slaydlar ko‘paytirilmasidan Slide Master’da sarlavha shrifti va maketni sozlash", "4) Slide Show rejimida sarlavha ko‘rinishi bir xilligini tekshirish"], "order": [2, 3, 1, 4]}, {"code": "M03-S26-P02-05", "prev_stem": "Rasmda birinchi effekt foydalanuvchi bosganda, ikkinchisi u bilan birga, uchinchisi ikkinchi effekt tugagach boshlanishi kerak. Bajariladigan sozlashlarni tartiblang.", "stem_md": "PowerPointdagi yangi slayd hali bo‘sh, unda uchta obyekt ham, animatsiya ham yo‘q. Uchinchi effekt ikkinchisidan so‘ng, ikkinchisi birinchisi bilan birga boshlanishi kerak. Amallarni tartiblang.", "explanation_md": "Avval obyektlar yaratiladi, keyin ularga animatsiya qo‘shiladi. Shundan keyingina Animation Pane’dagi tartib va Start: 1=On Click, 2=With Previous, 3=After Previous sozlanadi; oxirida namoyishda tekshiriladi. Bu tartib obyekt/effekt mavjud bo‘lishiga bog‘liq.", "difficulty": 5, "format": "Y3", "options": null, "steps": ["1) Slide Show’da uch effektning haqiqiy boshlanishini sinab ko‘rish", "2) Uchta obyektning har biriga Entrance animatsiyasini qo‘shish", "3) Slaydga uchta obyektni joylashtirish", "4) Animation Pane’da effektlarni 1–2–3 tartibga keltirib, `On Click`, `With Previous`, `After Previous` vaqtlarini sozlash"], "order": null}, {"code": "M03-S26-E04-03", "prev_stem": "Jadval: (Nomi, Fan, Ball) = (Ali, Informatika, 87), (Sami, Matematika, 79), (Olim, Informatika, 65), (Zebo, Informatika, 92). Fan=Informatika VA Ball≥80 filtri nechta satr ko‘rsatadi?", "stem_md": "Excel jadvalidagi (Fan, Ball) qatorlar: (Informatika, 87), (Matematika, 79), (Informatika, 65), (Informatika, 92), (Matematika, 84), (Informatika, 80). Fan=\"Informatika\" VA Ball≥80 filtri yoqilganda nechta satr ko‘rinadi va ularning ballari yig‘indisi nechaga teng?", "explanation_md": "Informatika satrlari 87,65,92,80. ≥80 mezoniga 87,92,80 mos: 3 ta satr, jami 87+92+80=259. Matematika qatorlari filtrdan o‘tmaydi. Yig‘indini barcha yozuvlarga emas, filtrga mos ko‘rinadigan yozuvlarga hisoblash kerak.", "difficulty": 4, "format": "Y1", "options": ["3 ta satr; yig‘indi 259", "4 ta satr; yig‘indi 324", "2 ta satr; yig‘indi 179", "3 ta satr; yig‘indi 244"], "steps": null, "order": null}, {"code": "M03-S26-P01-01", "prev_stem": "Taqdimotdagi barcha 50 slaydning sarlavha shriftini bir xil o‘zgartirish talab etildi. Qo‘lda har bir slaydni o‘zgartirmaslik uchun qaysi vosita afzal?", "stem_md": "PowerPointda 50 ta slayd Slide Master asosida yaratilgan. Master sarlavha shrifti o‘zgartirildi, ammo 8 slayddagi sarlavhalar avvalgidek qoldi — ular qo‘lda formatlangan. Qaysi yechim umumiy dizaynni qayta tiklaydi?", "explanation_md": "Slide Master umumiy formatni belgilaydi, lekin ayrim slaydlardagi qo‘lda qo‘yilgan lokal formatlar ustuvor bo‘lishi mumkin. Muammo qayta Master sozlash bilan birga lokal formatlashni tozalash, Reset yoki layoutni qayta qo‘llash orqali hal etiladi.", "difficulty": 5, "format": "Y1", "options": ["Faqat Rehearse Timings ni qayta ishga tushirish", "Barcha slaydlarga Transition → Fade berish", "Master’dagi umumiy shriftni sozlab, lokal formatlashni bekor qilish yoki kerakli slaydlarda Reset/Layout bilan maketni qayta qo‘llash", "Animation Pane’da har bir effektni o‘chirish"], "steps": null, "order": null}, {"code": "M03-S26-W03-01", "prev_stem": "Bir xil sertifikat maketi 125 o‘quvchi uchun tayyorlanadi. Ism, familiya va sinf Excel ro‘yxatida saqlangan. Har bir sertifikatni qo‘lda yozmaslik uchun optimal Office jarayoni qaysi?", "stem_md": "125 ta sertifikat uchun Word maketi va Excel ro‘yxati tayyor. Excel ro‘yxatidagi “Sinf” ustuni keyin o‘zgargan. Qaysi jarayon o‘zgargan ma’lumotlar bilan sertifikatlarni qayta yaratishga yordam beradi?", "explanation_md": "Mail Merge ma’lumot manbasidagi dolzarb yozuvlar asosida alohida sertifikatlar hosil qiladi. Manbaga ulanishni yangilash, ustun-maydon mosligini va oldindan ko‘rishni tekshirish zarur.", "difficulty": 4, "format": "Y1", "options": ["PowerPointda 125 ta mustaqil slayd yaratish", "Excelda faqat Sort qilish va avvalgi PDFni o‘zgartirmasdan tarqatish", "Word Mail Merge’da Excel manbasini tekshirish/yangilash, Merge Fields ni bog‘lash, Preview Results orqali tekshirish va Finish & Merge qilish", "Word Find & Replace bilan 125 ta ismni bittadan almashtirish"], "steps": null, "order": null}, {"code": "M03-S26-W03-02", "prev_stem": "Wordda rasm ustiga sarlavha sifatida qiyshaytirilgan bezakli matn qo‘yish kerak. Diagramma yoki jarayon bosqichlari talab qilinmaydi. Qaysi vosita eng bevosita mos?", "stem_md": "Wordda rasm ustiga sarlavha sifatida qiyshaytirilgan bezakli matn qo‘yish kerak. Diagramma yoki jarayon bosqichlari talab qilinmaydi. Qaysi vosita eng bevosita mos?", "explanation_md": "WordArt bezakli matn ko‘rinishlari uchun; SmartArt ko‘proq tarkibiy sxema/diagrammalar uchun ishlatiladi. 13-aprel manbasidagi obyektlarni farqlashga o‘xshash original vaziyat.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-E02-04", "prev_stem": "A1=12, B1=0. C1 katakdagi `=IFERROR(A1/B1,\"XATO\")` nimani qaytaradi?", "stem_md": "A1=12, B1=0. C1 katakdagi `=IFERROR(A1/B1,\"XATO\")` nimani qaytaradi?", "explanation_md": "A1/B1 nolga bo‘linadi, lekin IFERROR ikkinchi argumentdagi `XATO` matnini qaytaradi.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-E02-05", "prev_stem": "Excel formulasida `=SUM(A1:A5` yozilgan va yakuniy qavs qo‘yilmagan. Quyidagi fikrlarning qaysi biri eng aniq?", "stem_md": "Excel formulasida `=SUM(A1:A5` yozilgan va yakuniy qavs qo‘yilmagan. Quyidagi fikrlarning qaysi biri eng aniq?", "explanation_md": "Sintaktik qavs yetishmaydi; #REF! esa odatda yaroqsiz katak havolasi bilan bog‘liq.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-E03-03", "prev_stem": "Excelda quyidagi baholar jadvali bor: A2:B4 = (40,2), (60,3), (80,5). D2=60. `=VLOOKUP(D2,A2:B4,2,FALSE)` qanday qiymat qaytaradi?", "stem_md": "Excelda quyidagi baholar jadvali bor: A2:B4 = (40,2), (60,3), (80,5). D2=60. `=VLOOKUP(D2,A2:B4,2,FALSE)` qanday qiymat qaytaradi?", "explanation_md": "FALSE aynan 60 ni qidiradi va shu satrning 2-ustunidagi 3 qiymatini oladi.", "difficulty": 3, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-E03-05", "prev_stem": "A1=7, B1=−9. Excelda `=IF(AND(A1>0,B1<0),ABS(B1)+A1,0)` qiymat nechaga teng?", "stem_md": "A1=7, B1=−9. Excelda `=IF(AND(A1>0,B1<0),ABS(B1)+A1,0)` qiymat nechaga teng?", "explanation_md": "Ikkala shart rost, ABS(−9)+7=16.", "difficulty": 3, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-E04-01", "prev_stem": "Filtrdan so‘ng jadvalda faqat balli kamida 70 va tumani “Navoiy” bo‘lganlar ko‘rinsin. Qaysi shart to‘g‘ri?", "stem_md": "Filtrdan so‘ng jadvalda faqat balli kamida 70 va tumani “Navoiy” bo‘lganlar ko‘rinsin. Qaysi shart to‘g‘ri?", "explanation_md": "Ikkala talab bir vaqtda bajarilishi shart; Sort filtr o‘rnini bosmaydi.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-E04-02", "prev_stem": "Excelda A sinf 24, B sinf 36, C sinf 60 ta kitob to‘pladi. Jami bo‘yicha doiraviy diagrammada C sinf ulushi qanchaga teng?", "stem_md": "Excelda A sinf 24, B sinf 36, C sinf 60 ta kitob to‘pladi. Jami bo‘yicha doiraviy diagrammada C sinf ulushi qanchaga teng?", "explanation_md": "Jami 24+36+60=120; C sinf ulushi 60/120=50%. Diagrammadagi nisbiy ulush masalasi.", "difficulty": 3, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-P02-01", "prev_stem": "Bitta slaydda rasmga Entrance effekti, keyingi slaydga Fade o‘tish effekti berildi. Qaysi fikr to‘g‘ri?", "stem_md": "Bitta slaydda rasmga Entrance effekti, keyingi slaydga Fade o‘tish effekti berildi. Qaysi fikr to‘g‘ri?", "explanation_md": "Animation va Transition turli darajadagi effektlar: obyekt ichida vs slaydlar orasida.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-P02-02", "prev_stem": "Animation Pane’da 1-effekt “On Click”, 2-effekt “With Previous”, 3-effekt “After Previous” qilib berilgan. Ikkinchi effekt qachon ishga tushadi?", "stem_md": "Animation Pane’da 1-effekt “On Click”, 2-effekt “With Previous”, 3-effekt “After Previous” qilib berilgan. Ikkinchi effekt qachon ishga tushadi?", "explanation_md": "With Previous — oldingi effekt bilan birga boshlanadi; Delay alohida sozlama.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-P02-03", "prev_stem": "O‘qituvchi 12 slaydli taqdimotni har safar 15 soniyadan keyin avtomatik almashtirmoqchi. Qaysi sozlama mos?", "stem_md": "O‘qituvchi 12 slaydli taqdimotni har safar 15 soniyadan keyin avtomatik almashtirmoqchi. Qaysi sozlama mos?", "explanation_md": "Automatic slayd o‘tishi Advance Slide / After maydoni orqali sozlanadi; bosish bilan o‘tish alohida yoqilishi mumkin.", "difficulty": 2, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-P01-02", "prev_stem": "Taqdimotga video qo‘shilgandan keyin uni avtomatik boshlash va faqat slayd ichida ko‘rsatish kerak. Qaysi juft sozlama muhim?", "stem_md": "Taqdimotga video qo‘shilgandan keyin uni avtomatik boshlash va faqat slayd ichida ko‘rsatish kerak. Qaysi juft sozlama muhim?", "explanation_md": "Video ishga tushirish xulqi Playbackda belgilanadi; ko‘rinish slayd ichidagi obyekt xossasi bilan boshqariladi.", "difficulty": 3, "format": "Y1", "options": null, "steps": null, "order": null}, {"code": "M03-S26-P02-04", "prev_stem": "Animatsiya boshlanish turlari va bajarilish shartlarini moslang.", "stem_md": "Animatsiya boshlanish turlari va bajarilish shartlarini moslang.", "explanation_md": "1–C, 2–D, 3–A, 4–B; Delay alohida maydon va bu uch start turini almashtirmaydi.", "difficulty": 3, "format": "Y2", "options": null, "steps": null, "order": null}]'::jsonb) LOOP
    v_code := p->>'code';
    SELECT id,stem_md,status::text INTO v_id,v_stem,v_status FROM public.questions
    WHERE source_reference LIKE 'M03_STYLE_QA_2026|'||v_code||'|%' LIMIT 1 FOR UPDATE;
    IF v_id IS NULL THEN RAISE NOTICE 'TASK-281 missing review candidate %',v_code; CONTINUE; END IF;
    IF v_status <> 'review' THEN RAISE EXCEPTION 'TASK-281 cannot update non-review candidate %',v_code; END IF;
    IF v_stem NOT IN (p->>'prev_stem',p->>'stem_md') THEN RAISE EXCEPTION 'TASK-281 concurrent modification of %',v_code; END IF;
    UPDATE public.questions SET
      stem_md=p->>'stem_md',
      difficulty=(p->>'difficulty')::integer,
      cognitive=(CASE
        WHEN (p->>'difficulty')::integer >= 5 THEN 'mulohaza'
        WHEN (p->>'difficulty')::integer <= 2 THEN 'bilish'
        ELSE 'qollash' END)::public.cognitive_level
    WHERE id=v_id AND status='review'::public.content_status;
    UPDATE public.question_keys SET explanation_md=p->>'explanation_md' WHERE question_id=v_id;
    IF jsonb_typeof(p->'options')='array' THEN
      FOR i IN 0..3 LOOP
        UPDATE public.question_options SET content_md=p->'options'->>i
        WHERE question_id=v_id AND side='a' AND order_idx=i;
      END LOOP;
    END IF;
    IF jsonb_typeof(p->'steps')='array' THEN
      FOR i IN 0..3 LOOP
        UPDATE public.question_options SET content_md=regexp_replace(p->'steps'->>i,'^[0-9]+[)] ','')
        WHERE question_id=v_id AND side='a' AND order_idx=i;
      END LOOP;
    END IF;
    IF jsonb_typeof(p->'order')='array' THEN
      v_ord:='[]'::jsonb;
      FOR i IN 0..3 LOOP
        idx=(p->'order'->>i)::integer-1;
        IF idx < 0 OR idx > 3 THEN RAISE EXCEPTION 'Bad order %',v_code; END IF;
        v_opt=md5('m03-task280:'||v_code||':a:'||idx)::uuid;
        v_ord=v_ord||jsonb_build_array(v_opt::text);
      END LOOP;
      UPDATE public.question_keys SET payload=jsonb_build_object('order',v_ord)
        WHERE question_id=v_id;
    END IF;
  END LOOP;
END
$task281$;
COMMIT;
